cpp.source:
int arithmetic(short a, int b) { return (a + b) * 2; }
bool condition(int a, int b) { return !(a < b) || a == b; }
int converted(bool a) { return static_cast<int>(a); }

rust.source:
fn arithmetic(a: i8, b: i8) -> i8 { (a + b) * 2 }
fn condition(a: i8, b: i8) -> bool { !(a < b) || a == b }
fn converted(a: bool) -> i32 { a as i32 }

gdscript.source:
func arithmetic(a: int, b: int) -> int:
    return (a + b) * 2
func condition(a: int, b: int) -> bool:
    return not (a < b) or a == b
func converted(a: bool) -> int:
    return int(a)
